#!/usr/bin/env bash
# Generated by genproj — install the pinned gitleaks binary.
#
# gitleaks is a single static binary: no Go toolchain, no package manager, no
# account, no network at scan time. The version is PINNED and every download is
# checked against a sha256 — a binary that downloads but is not verified is the
# thing an attacker wants most.
#
# Bump the version and the three checksums together; never track "latest".
set -euo pipefail

VERSION="8.30.1"
INSTALL_DIR="${GITLEAKS_INSTALL_DIR:-$HOME/.local/bin}"
BIN="$INSTALL_DIR/gitleaks"

if [ -x "$BIN" ] && [ "$("$BIN" version 2>/dev/null | head -n 1)" = "$VERSION" ]; then
  echo "INFO: gitleaks $VERSION already installed at $BIN"
  exit 0
fi

case "$(uname -s)/$(uname -m)" in
  Linux/x86_64 | Linux/amd64)
    ASSET="linux_x64"
    SHA256="551f6fc83ea457d62a0d98237cbad105af8d557003051f41f3e7ca7b3f2470eb"
    ;;
  Linux/aarch64 | Linux/arm64)
    ASSET="linux_arm64"
    SHA256="e4a487ee7ccd7d3a7f7ec08657610aa3606637dab924210b3aee62570fb4b080"
    ;;
  Darwin/arm64)
    ASSET="darwin_arm64"
    SHA256="b40ab0ae55c505963e365f271a8d3846efbc170aa17f2607f13df610a9aeb6a5"
    ;;
  *)
    echo "ERROR: no pinned gitleaks $VERSION asset for $(uname -s)/$(uname -m)." >&2
    echo "ERROR: install gitleaks by hand, or add the asset and its sha256 here." >&2
    exit 1
    ;;
esac

fetch() {
  # `curl` is the common case; slim CI images often ship only `wget`.
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL "$1" -o "$2"
  elif command -v wget >/dev/null 2>&1; then
    wget -qO "$2" "$1"
  else
    echo "ERROR: neither curl nor wget is available; cannot download gitleaks." >&2
    exit 1
  fi
}

TMP_DIR=$(mktemp -d)
trap 'rm -rf "$TMP_DIR"' EXIT

URL="https://github.com/gitleaks/gitleaks/releases/download/v${VERSION}/gitleaks_${VERSION}_${ASSET}.tar.gz"
echo "INFO: Downloading gitleaks $VERSION ($ASSET)..."
fetch "$URL" "$TMP_DIR/gitleaks.tar.gz"

if command -v sha256sum >/dev/null 2>&1; then
  printf '%s  %s\n' "$SHA256" "$TMP_DIR/gitleaks.tar.gz" | sha256sum -c - >/dev/null
elif command -v shasum >/dev/null 2>&1; then
  printf '%s  %s\n' "$SHA256" "$TMP_DIR/gitleaks.tar.gz" | shasum -a 256 -c - >/dev/null
else
  echo "ERROR: no sha256 tool (sha256sum or shasum); refusing to install an unverified binary." >&2
  exit 1
fi

tar -xzf "$TMP_DIR/gitleaks.tar.gz" -C "$TMP_DIR" gitleaks
mkdir -p "$INSTALL_DIR"
install -m 0755 "$TMP_DIR/gitleaks" "$BIN"

echo "INFO: Installed gitleaks $VERSION at $BIN"
case ":$PATH:" in
  *":$INSTALL_DIR:"*) ;;
  *) echo "INFO: Add $INSTALL_DIR to PATH to run 'gitleaks' directly; the hook finds it there anyway." ;;
esac
